struct Gate { std::mutex m; std::condition_variable cv; unsigned n,arrived=0,g=0; explicit Gate(unsigned x):n(x){} void wait(){std::unique_lock<std::mutex>l(m);auto q=g;if(++arrived==n){arrived=0;++g;cv.notify_all();}else cv.wait(l,[&]{return g!=q;});} };
struct Cond { int W=0,O=0,m=0,K=0,R=1; bool calibrated_R=false; std::string id; };
struct Stamp { uint64_t t=0; int64_t q=0; unsigned lp=UINT_MAX; };
