void set_affinity(unsigned w);
uint64_t read_tsc(){_mm_lfence();unsigned a=0;uint64_t v=__rdtscp(&a);_mm_lfence();return v;}
double qualify_core_sync(double hz,int64_t qpf){struct P{uint64_t t=0;int64_t a=0,b=0;unsigned lp=UINT_MAX;};std::array<std::array<P,8>,31> samples{};Gate start(8),finish(8);std::vector<std::thread>ts;std::atomic<bool>ok{true};for(unsigned w=0;w<8;++w)ts.emplace_back([&,w]{try{set_affinity(w);for(int n=0;n<31;++n){start.wait();LARGE_INTEGER a{},b{};QueryPerformanceCounter(&a);auto t=read_tsc();unsigned lp=GetCurrentProcessorNumber();QueryPerformanceCounter(&b);samples[n][w]={t,a.QuadPart,b.QuadPart,lp};finish.wait();}}catch(...){ok=false;}});for(auto&t:ts)t.join();if(!ok)throw std::runtime_error("cross_core_sync_affinity_failed");double max_spread=0,max_qpc_bracket=0;for(int n=0;n<31;++n){std::vector<double>offsets;for(unsigned w=0;w<8;++w){auto&p=samples[n][w];if(p.lp!=worker_processor_r12(w).lp)throw std::runtime_error("cross_core_sync_migration");max_qpc_bracket=std::max(max_qpc_bracket,double(p.b-p.a)/qpf);double mid=(double(p.a)+double(p.b))/2.0;offsets.push_back(double(p.t)-mid*hz/double(qpf));}auto mm=std::minmax_element(offsets.begin(),offsets.end());max_spread=std::max(max_spread,(*mm.second-*mm.first)/hz);}if(max_qpc_bracket>.001||max_spread>.001)throw std::runtime_error("cross_core_TSC_sync_uncertainty_gt_1ms");return std::max(max_qpc_bracket,max_spread);}
double quantile(std::vector<double>v,double q){std::sort(v.begin(),v.end());double p=(v.size()-1)*q;size_t i=size_t(p);return v[i]+(p-i)*(v[std::min(i+1,v.size()-1)]-v[i]);}
bool page_large(const void*data,size_t bytes){if(!data||!bytes)return false;SYSTEM_INFO si{};GetSystemInfo(&si);uintptr_t a=reinterpret_cast<uintptr_t>(data),b=a+bytes-1,first=a&~(uintptr_t(si.dwPageSize)-1),last=b&~(uintptr_t(si.dwPageSize)-1);std::vector<PSAPI_WORKING_SET_EX_INFORMATION>q;for(uintptr_t p=first;;p+=si.dwPageSize){PSAPI_WORKING_SET_EX_INFORMATION z{};z.VirtualAddress=reinterpret_cast<void*>(p);q.push_back(z);if(p==last)break;}if(!QueryWorkingSetEx(GetCurrentProcess(),q.data(),DWORD(q.size()*sizeof(q[0]))))return false;for(auto&z:q)if(!z.VirtualAttributes.Valid||!z.VirtualAttributes.LargePage)return false;return true;}
bool clflushopt_available(){int x[4]{};__cpuidex(x,7,0);return (x[1]&(1<<23))!=0;}
void flush_region(const void*data,size_t bytes,bool opt){auto*p=reinterpret_cast<const char*>(data);for(size_t i=0;i<bytes;i+=64){if(opt)_mm_clflushopt(p+i);else _mm_clflush(p+i);}if(opt)_mm_sfence();else _mm_mfence();}
void set_affinity(unsigned w){if(!set_worker_affinity_r12(w)||!worker_affinity_matches_r12(w))throw std::runtime_error("GetLogicalProcessorInformationEx worker affinity mismatch or migration");}
std::vector<Cond> read_conditions(const std::string&path){std::ifstream f(path);if(!f)throw std::runtime_error("conditions_csv_open_failed:"+path);std::vector<Cond>out;std::string line;bool head=true,has_r=false;while(std::getline(f,line)){if(head){head=false;if(line=="condition,W_target_kib,O,m,K")has_r=false;else if(line=="condition,W_target_kib,O,m,K,R")has_r=true;else throw std::runtime_error("conditions_csv_header_invalid");continue;}if(line.empty())continue;std::stringstream ss(line);std::string a,b,c,d,e,r;if(!std::getline(ss,a,',')||!std::getline(ss,b,',')||!std::getline(ss,c,',')||!std::getline(ss,d,',')||!std::getline(ss,e,','))throw std::runtime_error("conditions_csv_row_invalid");Cond z;z.id=a;z.W=std::stoi(b);z.O=std::stoi(c);z.m=std::stoi(d);z.K=std::stoi(e);if(has_r){if(!std::getline(ss,r,','))throw std::runtime_error("conditions_csv_R_missing");z.R=std::stoi(r);z.calibrated_R=true;}std::string extra;if(std::getline(ss,extra,','))throw std::runtime_error("conditions_csv_extra_column");if(z.O<8||z.O>omega_q4::kOutputMax||z.O%8||!(z.m==1||z.m==4||z.m==8||z.m==16)||!(z.K==1||z.K==2||z.K==4||z.K==8||z.K==16)||z.R<1||z.R>1000000)throw std::runtime_error("conditions_csv_geometry_or_R_invalid:"+line);out.push_back(z);}if(out.empty())throw std::runtime_error("conditions_csv_empty");return out;}
void prepare_worker(Worker&w,const Cond&c,unsigned worker,bool multi){(void)worker;w.cell=r11::generate_cell(c.m,c.O);auto b=std::make_unique<omega_q4::PackedWeights>();omega_q4::prepare_weights(w.cell,c.O,*b);w.weights.push_back(std::move(b));if(multi)for(int k=1;k<c.K;++k){auto copy=std::make_unique<omega_q4::PackedWeights>();copy->output=c.O;copy->bytes.resize(omega_q4::weight_bytes(c.O));std::memcpy(copy->bytes.data(),w.weights[0]->bytes.data(),omega_q4::weight_bytes(c.O));w.weights.push_back(std::move(copy));}for(size_t a=0;a<w.weights.size();++a){if(std::memcmp(w.weights[a]->bytes.data(),w.weights[0]->bytes.data(),omega_q4::weight_bytes(c.O))!=0)throw std::runtime_error("B_copy_content_mismatch");for(size_t b=a+1;b<w.weights.size();++b){auto x=reinterpret_cast<uintptr_t>(w.weights[a]->bytes.data()),y=reinterpret_cast<uintptr_t>(w.weights[b]->bytes.data());if(!(x+omega_q4::weight_bytes(c.O)<=y||y+omega_q4::weight_bytes(c.O)<=x))throw std::runtime_error("B_weight_regions_overlap");}}omega_q4::prepare_activations(w.cell,c.O,w.x);w.y.resize(size_t(c.m)*c.O);w.large=w.x.bytes.is_large()&&w.y.is_large();for(auto&z:w.weights)w.large=w.large&&z->bytes.is_large();std::vector<std::int8_t>wq,xq;std::vector<std::uint16_t>ws,xs;if(!omega_q4::qa_reconstruct(*w.weights[0],wq,ws)||!omega_q4::qa_reconstruct_activations(w.x,xq,xs)||wq!=w.cell.wq||ws!=w.cell.ws_half||xq!=w.cell.xq||xs!=w.cell.xs_half)throw std::runtime_error("exact_representation_failed");std::vector<int32_t>dots(size_t(c.m)*c.O*r11::G);omega_q4::qa_group_dots(*w.weights[0],w.x,dots.data());for(int m=0;m<c.m;++m)for(int o=0;o<c.O;++o)for(int g=0;g<r11::G;++g){int32_t d=0;for(int k=0;k<32;++k)d+=int(w.cell.wq[size_t(o)*r11::I+g*32+k])*int(w.cell.xq[size_t(m)*r11::I+g*32+k]);if(dots[(size_t(m)*c.O+o)*r11::G+g]!=d)throw std::runtime_error("exact_group_dot_failed");}omega_q4::run(*w.weights[0],w.x,c.O,w.y.data());auto v=r11::verify_s12(w.cell,c.O,w.y.data(),w.y.size());if(!v.pass)throw std::runtime_error("S12_numeric_check_failed");for(auto&z:w.weights)if(!page_large(z->bytes.data(),omega_q4::weight_bytes(c.O)))throw std::runtime_error("large_page_check_failed:weights");if(!page_large(w.x.bytes.data(),w.x.bytes.size())||!page_large(w.y.data(),w.y.size()*sizeof(float)))throw std::runtime_error("large_page_check_failed:nonweights");w.affinity=true;}
void condition_nonweights(Worker&w){auto a=read_tsc();const auto*p=reinterpret_cast<const volatile uint8_t*>(w.x.bytes.data());uint64_t sum=0;for(size_t i=0;i<w.x.bytes.size();i+=64)sum+=p[i];w.sink^=sum;std::fill(w.y.begin(),w.y.end(),0.5f);_mm_mfence();auto b=read_tsc();w.condition_us+=double(b-a);}
double median(std::vector<double>v){return quantile(std::move(v),.5);}
uint64_t timestamp_pair_overhead(){std::vector<double>v;v.reserve(2048);for(int i=0;i<2048;++i){auto a=read_tsc();auto b=read_tsc();v.push_back(double(b-a));}return uint64_t(median(std::move(v)));}
std::string json_escape(const std::string&s){std::string o;for(char c:s){if(c=='"'||c=='\\')o.push_back('\\');o.push_back(c);}return o;}
