      const char variant=char('A'+vi);const bool multi=variant=='B';std::atomic<bool>setup{true};
      Gate ready(8),prepDone(8),episodeStart(8),appStart(8),appDone(8),appMetricDone(8),episodeDone(8);std::vector<std::thread>threads;
      std::vector<App>apps(sample_count);for(auto&app:apps){app.start.resize(8);app.end.resize(8);}
      std::vector<std::vector<std::vector<Stamp>>>app_starts(sample_count,std::vector<std::vector<Stamp>>(c.K,std::vector<Stamp>(8))),app_ends(sample_count,std::vector<std::vector<Stamp>>(c.K,std::vector<Stamp>(8)));
      std::vector<std::vector<std::vector<uint64_t>>>app_addresses(sample_count,std::vector<std::vector<uint64_t>>(8,std::vector<uint64_t>(c.K)));
      std::vector<std::vector<std::vector<double>>>flush_app_us(sample_count,std::vector<std::vector<double>>(8,std::vector<double>(c.K))),condition_app_us(sample_count,std::vector<std::vector<double>>(8,std::vector<double>(c.K))),barrier_app_us(sample_count,std::vector<std::vector<double>>(8,std::vector<double>(c.K)));
