            LARGE_INTEGER qb{},qpre{},qpost{},qdone{};QueryPerformanceCounter(&qb);appStart.wait();QueryPerformanceCounter(&qpre);auto t0=read_tsc();const unsigned slot=variant=='B'?unsigned(app):0;
            app_starts[rep][app][worker]={t0,qpre.QuadPart,GetCurrentProcessorNumber()};app_addresses[rep][worker][app]=reinterpret_cast<uint64_t>(w[worker]->weights[slot]->bytes.data());
            omega_q4::run(*w[worker]->weights[slot],w[worker]->x,c.O,w[worker]->y.data());auto t1=read_tsc();QueryPerformanceCounter(&qpost);app_ends[rep][app][worker]={t1,qpost.QuadPart,GetCurrentProcessorNumber()};apps[rep].start[worker]=app_starts[rep][app][worker];apps[rep].end[worker]=app_ends[rep][app][worker];
